import java.io.*;
import java.util.*;

public class Main {
    static final int mod = 1000000007;
    static final int maxn = 20;
    static final int N = 2001000;
    static int[] f = new int[N];
    static int[] g = new int[N];
    static int[] b = new int[N];
    static int[] mp = new int[1 << maxn];
    static int[] tot = new int[maxn + 1];
    static ArrayList<Integer>[] v = new ArrayList[maxn + 1];
    static int n;

    static int pow(int a, int b) {
        int ans = 1;
        while (b > 0) {
            if ((b & 1) == 1) ans = (int)((long)ans * a % mod);
            a = (int)((long)a * a % mod);
            b >>= 1;
        }
        return ans;
    }

    static int inv(int a) {
        return pow(a, mod - 2);
    }

    static void reduce(int[] x, int idx) {
        x[idx] += (x[idx] >> 31) & mod;
    }

    static int fac(int x) {
        if (x == 0) return 1;
        return (int)((long)fac(x - 1) * x % mod);
    }

    static int C(int n, int m) {
        return (int)((long)fac(n) * inv(fac(m)) % mod * inv(fac(n - m)) % mod);
    }

    static int pc(int x) {
        return Integer.bitCount(x);
    }

    static int ctz(int x) {
        return Integer.numberOfTrailingZeros(x);
    }

    static void fwt(int[] a, int lim) {
        if ((lim /= 2) == 0) return;
        for (int i = 0; i < lim; ++i) {
            a[i] += a[i + lim] - mod;
            reduce(a, i);
        }
        fwt(a, lim);
        fwt(a, lim);
    }

    static void fwt2(int[] a, int lim) {
        if ((lim /= 2) == 0) return;
        for (int i = 0; i < lim; ++i) {
            a[i] -= a[i + lim];
            reduce(a, i);
        }
        fwt2(a, lim);
        fwt2(a, lim);
    }

    static boolean nextPermutation(int[] a, int len) {
        int i = len - 2;
        while (i >= 0 && a[i] >= a[i + 1]) i--;
        if (i < 0) return false;
        int j = len - 1;
        while (a[j] <= a[i]) j--;
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
        int left = i + 1, right = len - 1;
        while (left < right) {
            tmp = a[left];
            a[left] = a[right];
            a[right] = tmp;
            left++;
            right--;
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        int[][] a = new int[maxn][maxn];
        for (int i = 0; i < n; ++i) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < n; ++j) {
                a[i][j] = Integer.parseInt(st.nextToken());
                a[i][j] = (int)((long)a[i][j] * inv(100) % mod);
                b[i * n + j] = a[i][j];
            }
        }

        for (int i = 0; i <= n; ++i) v[i] = new ArrayList<>();
        for (int i = 0; i < (1 << n); ++i) {
            v[pc(i)].add(i);
            tot[pc(i)]++;
        }
        for (int i = 0; i < (1 << n); ++i) {
            mp[i] = --tot[pc(i)];
        }

        int m = n / 2;
        int M = n - m;

        // First half
        int lim1 = 1 << (m * n);
        for (int i = 0; i < lim1; ++i) {
            int p = 1;
            for (int j = 0; j < m * n; ++j) {
                p = (int)((long)p * ((i >> j & 1) == 1 ? b[j] : mod + 1 - b[j]) % mod);
            }
            int[] S = new int[3];
            for (int j = 0; j < m; ++j) {
                S[j] = (i >> (j * n)) & ((1 << n) - 1);
            }
            int st = 0;
            for (int j : v[m]) {
                int[] s = new int[m];
                int totcnt = 0;
                for (int k = j; k != 0; k &= k - 1) {
                    s[totcnt++] = ctz(k);
                }
                Arrays.sort(s, 0, m);
                do {
                    boolean ok = true;
                    for (int jj = 0; jj < m; ++jj) {
                        if (((S[jj] >> s[jj]) & 1) == 0) {
                            ok = false;
                            break;
                        }
                    }
                    if (ok) {
                        st |= 1 << mp[j];
                        break;
                    }
                } while (nextPermutation(s, m));
            }
            f[st] += p - mod;
            reduce(f, st);
        }

        // Second half
        int lim2 = 1 << (M * n);
        for (int i = 0; i < lim2; ++i) {
            int p = 1;
            for (int j = 0; j < M * n; ++j) {
                p = (int)((long)p * ((i >> j & 1) == 1 ? b[j + n * m] : mod + 1 - b[j + n * m]) % mod);
            }
            int[] S = new int[3];
            for (int j = 0; j < M; ++j) {
                S[j] = (i >> (j * n)) & ((1 << n) - 1);
            }
            int st = 0;
            for (int j : v[n - m]) {
                int[] s = new int[M];
                int totcnt = 0;
                for (int k = j; k != 0; k &= k - 1) {
                    s[totcnt++] = ctz(k);
                }
                Arrays.sort(s, 0, M);
                do {
                    boolean ok = true;
                    for (int jj = 0; jj < M; ++jj) {
                        if (((S[jj] >> s[jj]) & 1) == 0) {
                            ok = false;
                            break;
                        }
                    }
                    if (ok) {
                        st |= 1 << mp[(~j) & ((1 << n) - 1)];
                        break;
                    }
                } while (nextPermutation(s, M));
            }
            g[st] += p - mod;
            reduce(g, st);
        }

        int totm = tot[m]; // number of subsets of size m
        int size = 1 << totm;
        fwt(f, size);
        fwt(g, size);
        for (int i = 0; i < size; ++i) {
            f[i] = (int)((long)f[i] * g[i] % mod);
        }
        fwt2(f, size);
        int ans = 0;
        for (int i = 1; i < size; ++i) {
            ans += f[i] - mod;
            reduce(new int[]{ans}, 0);
        }
        System.out.println(ans);
    }
}
